result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "influence.py", "content": """"Influence-map tower placement.

Map convention:
    digits '0'-'9' -> enemy spawn intensity
    '-'            -> buildable ground (no threat source)
"""


def parse_map(ascii_map):
    """Parse ASCII map into (grid, buildable) where grid holds threat sources."""
    rows = [line for line in ascii_map.strip().splitlines() if line.strip()]
    grid, buildable = [], []
    for r, row in enumerate(rows):
        row = row.strip()
        grid.append([0.0] * len(row))
        buildable.append([])
        for c, ch in enumerate(row):
            if ch.isdigit():
                grid[r][c] = float(int(ch))
                buildable[r].append(c)
            elif ch == "-":
                buildable[r].append(c)
            else:
                raise ValueError(f"unexpected map char {ch!r} at {(r, c)}")
    return grid, buildable


def diffuse(grid):
    """Each cell's threat = sum over spawns of intensity / (1 + manhattan_distance)."""
    h, w = len(grid), len(grid[0])
    spawns = [
        (r, c, grid[r][c])
        for r in range(h)
        for c in range(w)
        if grid[r][c] > 0
    ]
    threat = [[0.0] * w for _ in range(h)]
    for r in range(h):
        for c in range(w):
            threat[r][c] = sum(
                intensity / (1 + abs(r - sr) + abs(c - sc))
                for sr, sc, intensity in spawns
            )
    return threat


def placement_score(threat, r, c):
    """Total threat covered by a tower: Chebyshev-radius-1 neighborhood."""
    h, w = len(threat), len(threat[0])
    total = 0.0
    for dr in (-1, 0, 1):
        for dc in (-1, 0, 1):
            rr, cc = r + dr, c + dc
            if 0 <= rr < h and 0 <= cc < w:
                total += threat[rr][cc]
    return total


def best_placement(ascii_map):
    """Argmax-scored buildable cell; ties broken by row-major order."""
    grid, buildable = diffuse_map(ascii_map)
    threat = diffuse(grid)
    best_cell, best_score = None, float("-inf")
    for r in range(len(grid)):
        for c in buildable[r]:
            score = placement_score(threat, r, c)
            if score > best_score:  # strict > keeps first (row-major) on ties
                best_cell, best_score = (r, c), score
    return best_cell, best_score


def diffuse_map(ascii_map):
    return parse_map(ascii_map)
